import{_ as n,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Dessiner avec SVG-Line et SVG LineBox","description":"","frontmatter":{"title":"Dessiner avec SVG-Line et SVG LineBox"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/zeichnen.md","filePath":"fr/projects/grafik-visual-studio/zeichnen.md","lastUpdated":1793447386000}'),r={name:"fr/projects/grafik-visual-studio/zeichnen.md"};function o(a,e,l,u,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="zeichnen-svg-line-und-svg-linebox" tabindex="-1">Dessin : SVG-Line et SVG LineBox <a class="header-anchor" href="#zeichnen-svg-line-und-svg-linebox" aria-label="Permalink to &quot;Dessin : SVG-Line et SVG LineBox {#zeichnen-svg-line-und-svg-linebox}&quot;">​</a></h1><p>Les guides complets sont disponibles sur des pages dédiées : <a href="/fr/projects/grafik-visual-studio/svg-line">SVG-Line – Lignes de connexion et animation</a> et <a href="/fr/projects/grafik-visual-studio/svg-linebox">SVG LineBox – Collecte et transmission de valeurs</a> · <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">SVG LineBox Math</a>. La page consacrée à la LineBox intègre également des vidéos pour l&#39;éditeur et l&#39;environnement d&#39;exécution (runtime). Cette vue d&#39;ensemble est conservée pour assurer la pérennité des liens existants.</p><p>Le widget de ligne est disponible dans la palette sous <strong>HA Grafik – Spezial → SVG-Line</strong>. Il permet, par exemple, de relier visuellement deux panneaux solaires à un onduleur ou de regrouper plusieurs flux en un point de convergence. Pour l&#39;animation, SVG-Line peut lire une entité Home Assistant ; quant à la SVG LineBox, elle permet d&#39;additionner les valeurs numériques issues de plusieurs lignes et de les transmettre à une ligne de sortie.</p><h2 id="eine-verbindung-zeichnen" tabindex="-1">Dessiner une connexion <a class="header-anchor" href="#eine-verbindung-zeichnen" aria-label="Permalink to &quot;Dessiner une connexion {#eine-verbindung-zeichnen}&quot;">​</a></h2><ol><li>Insérez un élément <strong>SVG-Line</strong> (ligne SVG) et sélectionnez-le. Ses deux extrémités apparaissent sous forme de cercles déplaçables. Faites glisser une extrémité libre vers un point d&#39;ancrage situé sur un autre widget. Vous pouvez également, via les options <strong>Début</strong> et <strong>Fin</strong>, sélectionner un widget ainsi qu&#39;un point d&#39;ancrage spécifique, ou saisir manuellement des coordonnées X/Y.</li><li>Activez le groupe de propriétés <strong>Points d&#39;ancrage</strong> sur le widget cible. Pour les nouveaux widgets, les douze positions sont désactivées par défaut. L&#39;option <strong>Tous les points</strong> permet de les activer ou de les désactiver simultanément ; si seule une partie des points est sélectionnée, un état mixte s&#39;affiche. Les points peuvent aussi être activés individuellement : à gauche et à droite (en haut, au milieu, en bas) ; en haut et en bas (à 1/4, au milieu et à 3/4 de la largeur). La case à cocher située dans l&#39;en-tête du groupe permet d&#39;activer ou de désactiver l&#39;ensemble de la zone. Il est possible de configurer l&#39;affectation multiple, le nombre maximal de connexions, l&#39;espacement des lignes ainsi que l&#39;affichage permanent.</li><li>Choisissez le <strong>type de tracé</strong> : droit, à angles droits automatiques, courbe, ou tracé manuel en zigzag/à points multiples. Un clic sur la ligne fait apparaître, en son centre, la boîte de dialogue <strong>Point intermédiaire</strong> ou <strong>Point de regroupement</strong> ; « Point intermédiaire » est sélectionné par défaut. Après validation par <strong>OK</strong>, un point intermédiaire déplaçable est créé et le tracé passe en mode manuel à points multiples. Ces points peuvent également être nommés et positionnés via des coordonnées X/Y dans l&#39;éditeur de propriétés.</li></ol><p>Un <strong>point de regroupement</strong> activé peut servir de point de départ ou d&#39;arrivée pour une autre ligne. Vous pouvez également faire glisser une extrémité de ligne libre vers un point de regroupement visible : elle s&#39;y fixera, mémorisant ainsi la connexion. Le simple croisement de lignes ou leur proximité spatiale ne suffit jamais à établir une connexion. Si vous désactivez le point de regroupement, aucune nouvelle ligne ne s&#39;y rattachera. Plusieurs lignes peuvent aboutir à un point de regroupement activé. Pour les lignes qui, jusqu&#39;à présent, ne faisaient qu&#39;effleurer visuellement le point, vous devez procéder à un nouveau raccordement.</p><h2 id="aussehen-und-fluss" tabindex="-1">Apparence et flux <a class="header-anchor" href="#aussehen-und-fluss" aria-label="Permalink to &quot;Apparence et flux {#aussehen-und-fluss}&quot;">​</a></h2><ul><li><strong>Ligne :</strong> Couleur de base, seconde couleur d&#39;animation, épaisseur, opacité, style (continu/pointillés/tirets), longueur des traits et des espaces, extrémités des lignes et rayon des angles.</li><li><strong>Pointes de flèche :</strong> Définies séparément pour le début et la fin ; choix parmi : aucune, flèche pleine, flèche évidée ou cercle. La taille et la couleur sont réglables.</li><li><strong>Animation :</strong> Flux bicolore, traits en mouvement, effet de pulsation ou point lumineux. Sous <strong>Source de direction</strong>, une seule option peut être active : <strong>Manuel</strong> (avec définition de la direction et de la durée), <strong>Entité numérique</strong> ou <strong>Entité booléenne</strong>. Pour une entité numérique, une valeur positive indique un mouvement du début vers la fin, une valeur négative de la fin vers le début, et zéro signifie l&#39;arrêt. La valeur absolue divisée par le <strong>Diviseur</strong> (par défaut : 1) détermine le nombre de cycles par seconde (plage autorisée : 0,05 à 20). Exemple : 1000 W ÷ 100 = 10 cycles/s. L&#39;entité booléenne permet de définir le sens : <code>on</code>/<code>true</code>/<code>1</code> pour le sens direct, et <code>off</code>/<code>false</code>/<code>0</code> pour le sens inverse ; cette attribution peut être inversée. Si l&#39;état est indisponible ou invalide, l&#39;animation s&#39;arrête. Les pointes de flèche suivent la direction active. Le moteur d&#39;exécution (runtime) interroge régulièrement l&#39;entité HA sélectionnée. Grâce à l&#39;option <strong>Reprendre le rythme d&#39;animation de la ligne principale</strong>, une ligne secondaire suit le rythme de sa ligne principale tout en conservant ses propres couleurs durant l&#39;animation. Si elle est raccordée à un point de jonction de la ligne principale et que cette dernière n&#39;est pas animée, la ligne secondaire s&#39;arrête également et affiche la couleur de base de la ligne principale, pointes de flèche incluses. Vos paramètres de couleur et d&#39;animation personnalisés sont conservés et restent actifs même après la dissociation. La synchronisation permet d&#39;obtenir une cadence identique ou une arrivée simultanée au point de convergence. En cas de définition manuelle d&#39;une direction vers un point de convergence, l&#39;animation s&#39;oriente automatiquement vers ce point.</li><li><strong>Croisements et empilement :</strong> Superposition, espace visuel ou pont/arche, ainsi qu&#39;un mode « z-index » (ordre d&#39;empilement) réglable sur « automatique », « au-dessus », « en-dessous » ou manuellement. Un z-index plus élevé place l&#39;élément visuellement devant un élément ayant un z-index plus faible ; cela ne crée aucune connexion.</li></ul><h2 id="bearbeiten" tabindex="-1">Modification <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Modification {#bearbeiten}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Manipulation</th></tr></thead><tbody><tr><td>Déplacer un point d&#39;extrémité libre</td><td>Faire glisser le cercle ou déplacer le cercle sélectionné à l&#39;aide des touches fléchées ; <code>Umschalt</code> permet de faire passer le pas de déplacement de 1 à 10 pixels.</td></tr><tr><td>Détacher un point d&#39;extrémité</td><td>Maintenir <code>Strg</code> enfoncé tout en faisant glisser le cercle ; l&#39;utilisation de <code>Strg</code> combinée à une touche fléchée est également possible.</td></tr><tr><td>Déplacer un point intermédiaire</td><td>Sélectionner la ligne et faire glisser le point.</td></tr><tr><td>Déplacer la ligne entière</td><td>Cliquer sur la ligne et la faire glisser. Les points d&#39;ancrage de départ ou d&#39;arrivée existants seront alors supprimés.</td></tr><tr><td>Ajouter un point sur la ligne</td><td>Cliquer sur la ligne (sans faire glisser), choisir le type de point et confirmer avec <strong>OK</strong>.</td></tr></tbody></table><p>Ce widget est en phase expérimentale. L&#39;affichage des croisements et des animations synchronisées peut encore faire l&#39;objet d&#39;améliorations, en fonction du tracé du chemin et du navigateur utilisé.</p><h2 id="linebox-als-unsichtbarer-verteiler" tabindex="-1">SVG LineBox en tant que répartiteur invisible {#linebox-als-unsichtbarer-verteiler} <a class="header-anchor" href="#linebox-als-unsichtbarer-verteiler" aria-label="Permalink to &quot;SVG LineBox en tant que répartiteur invisible {#linebox-als-unsichtbarer-verteiler} {#linebox-als-unsichtbarer-verteiler}&quot;">​</a></h2><p>L&#39;éditeur met régulièrement à jour les états des entités numériques et booléennes sélectionnées. Cela permet de vérifier les animations de lignes SVG ainsi que la valeur calculée de la SVG LineBox avant même de passer en mode exécution (Runtime).</p><p>L&#39;élément <strong>HA Grafik – Spezial → SVG LineBox</strong> est visible et déplaçable dans l&#39;éditeur. En mode exécution, son cadre reste invisible ; les lignes qui y sont raccordées se rejoignent en son centre. À cet endroit, un cercle est placé par défaut au-dessus des extrémités des lignes, masquant ainsi leur terminaison anguleuse. Dans la section <strong>Point de connexion</strong> (<em>Verbindungspunkt</em>), vous pouvez masquer ce cercle, mais aussi définir son diamètre, sa couleur de remplissage, la couleur de son contour et l&#39;épaisseur de ce dernier. Si les lignes sont épaisses, le cercle s&#39;agrandit automatiquement si nécessaire afin de continuer à masquer les extrémités. L&#39;option <strong>Afficher la valeur de sortie</strong> (<em>Ausgabewert anzeigen</em>) propose les positions suivantes : <strong>Désactivé</strong> (par défaut), <strong>Au-dessus du cercle</strong> et <strong>En dessous du cercle</strong>. La valeur affichée correspond à la somme signée des entrées et se met à jour en temps réel, y compris lors du déplacement d&#39;un curseur (slider). La SVG LineBox dispose des douze points d&#39;ancrage habituels, comme les autres widgets. Par défaut, ils sont tous désactivés ; activez uniquement ceux dont vous avez besoin dans la section <strong>Points d&#39;ancrage</strong> (<em>Andockpunkte</em>). Sous <strong>Connexions</strong> (<em>Anschlüsse</em>), chaque point actif se voit alors attribuer un rôle : <strong>Entrée</strong>, <strong>Position zéro</strong> ou <strong>Sortie</strong>. La « Position zéro » est le réglage par défaut et n&#39;intervient pas dans le calcul. Les points désactivés ne permettent pas de choisir un rôle. Dans l&#39;éditeur, les différents points d&#39;ancrage restent distincts ; les points définis sur « Position zéro » ne sont pas reliés au point central commun.</p><p>Pour effectuer un test, reliez deux lignes SVG aux entrées de la SVG LineBox, et une troisième ligne SVG à une sortie. Pour les deux lignes d&#39;entrée, sélectionnez <strong>Entité numérique</strong> (Zahlen-Entität) sous <strong>Animation → Source de direction</strong> (Richtungsquelle) et saisissez un identifiant d&#39;entité (Entity ID) Home Assistant valide. Si les lignes d&#39;entrée aboutissent à la « SVG LineBox », leurs valeurs signées sont additionnées. Exemple : <code>1000</code> et <code>-300</code> donnent <code>700</code>. Une ligne qui part de la « SVG LineBox » est prise en compte à l&#39;entrée avec un signe inversé. Les états manquants ou invalides ne sont pas comptabilisés.</p><p>Réglez le point de départ sur <strong>Sortie</strong> et activez l&#39;option <strong>Transmettre la valeur calculée</strong> (désactivée par défaut). Activez l&#39;animation sur la ligne de sortie ; celle-ci utilisera alors le signe et la valeur absolue de la somme pour déterminer la direction et la vitesse. Le paramètre <strong>Diviseur SVG LineBox (lors de la transmission)</strong> permet de définir le rapport : avec <code>700</code> et un diviseur de <code>100</code>, la ligne se déplace à une cadence de 7 cycles/s. Les couleurs, les pointes de flèche et le style de ligne d&#39;origine sont conservés. Si la somme est <code>0</code> ou en l&#39;absence d&#39;entrée valide, l&#39;animation s&#39;arrête. Si vous désactivez la transmission au niveau de la sortie, la ligne reprendra ses propres paramètres d&#39;animation.</p><p>Le calcul et la transmission s&#39;effectuent normalement en interne. Via la rubrique <strong>Sortie vers entité auxiliaire (Helper)</strong>, vous pouvez également écrire la somme dans une entité auxiliaire (<code>input_number</code>) afin de pouvoir l&#39;utiliser ailleurs dans Home Assistant. La transmission interne reste active. L&#39;écriture ne se produit que lorsque la valeur de la somme change ; pour éviter toute boucle de rétroaction, il est impossible d&#39;utiliser comme entité auxiliaire une entité qui sert simultanément de source d&#39;entrée pour la même SVG LineBox. La plage de valeurs de l&#39;entité auxiliaire doit être compatible avec les valeurs que peut prendre la somme.</p><p>La première version utilise des entités de type « nombre » (number entities) sur les lignes d&#39;entrée. Il n&#39;existe pas encore de contrôle d&#39;entité spécifique pour chaque connexion de la SVG LineBox.</p><p>L&#39;ancien nom « Linebox » reste disponible en tant que terme de recherche dans la palette. Les projets enregistrés continuent d&#39;utiliser le type de widget technique <code>linebox</code> ; les noms personnalisés attribués aux widgets ne sont pas modifiés.</p>',19)])])}const g=n(r,[["render",o]]);export{m as __pageData,g as default};
